def apply_discount(total_cents: int, discount_bps: int) -> int:
    if isinstance(total_cents, bool) or not isinstance(total_cents, int):
        raise TypeError('total_cents must be an integer')
    if isinstance(discount_bps, bool) or not isinstance(discount_bps, int):
        raise TypeError('discount_bps must be an integer')
    if total_cents < 0:
        raise ValueError('total_cents must be non-negative')
    if not 0 <= discount_bps <= 10000:
        raise ValueError('discount_bps must be between 0 and 10000')
    return total_cents * (10000 - discount_bps) // 10000

